AVL Tree Implementation in Python
An AVL tree is a self-balancing binary search tree where the difference 
between heights of left and right subtrees cannot be more than one.
"""

class Node:
    """Tree node containing key, value, height, and child pointers."""

    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.height = 1
        self.left = None
        self.right = None


class AVLTree:
    """Self-balancing AVL Tree implementation."""

    def __init__(self):
        self.root = None

    def get_height(self, node):
        """Get height of a node."""
        if not node:
            return 0
        return node.height

    def get_balance(self, node):
        """Get balance factor of a node."""
        if not node:
            return 0
        return self.get_height(node.left) - self.get_height(node.right)

    def update_height(self, node):
        """Update height of a node based on children."""
        if node:
            node.height = 1 + max(
                self.get_height(node.left),
                self.get_height(node.right)
            )

    def rotate_right(self, y):
        """Perform right rotation."""
        x = y.left
        T2 = x.right

        x.right = y
        y.left = T2

        self.update_height(y)
        self.update_height(x)

        return x

    def rotate_left(self, x):
        """Perform left rotation."""
        y = x.right
        T2 = y.left

        y.left = x
        x.right = T2

        self.update_height(x)
        self.update_height(y)

        return y

    def insert(self, key, value=None):
        """Insert a key into the AVL tree."""
        self.root = self._insert(self.root, key, value)

    def _insert(self, node, key, value):
        """Recursive helper for insertion."""
        if not node:
            return Node(key, value)

        if key < node.key:
            node.left = self._insert(node.left, key, value)
        elif key > node.key:
            node.right = self._insert(node.right, key, value)
        else:
            node.value = value  # Update value if key exists
            return node

        self.update_height(node)
        balance = self.get_balance(node)

        # Left Left Case
        if balance > 1 and key < node.left.key:
            return self.rotate_right(node)

        # Right Right Case
        if balance < -1 and key > node.right.key:
            return self.rotate_left(node)

        # Left Right Case
        if balance > 1 and key > node.left.key:
            node.left = self.rotate_left(node.left)
            return self.rotate_right(node)

        # Right Left Case
        if balance < -1 and key < node.right.key:
            node.right = self.rotate_right(node.right)
            return self.rotate_left(node)

        return node

    def delete(self, key):
        """Delete a key from the AVL tree."""
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        """Recursive helper for deletion."""
        if not node:
            return node

        if key < node.key:
            node.left = self._delete(node.left, key)
        elif key > node.key:
            node.right = self._delete(node.right, key)
        else:
            # Node with only one child or no child
            if not node.left:
                return node.right
            elif not node.right:
                return node.left

            # Node with two children
            temp = self._min_value_node(node.right)
            node.key = temp.key
            node.value = temp.value
            node.right = self._delete(node.right, temp.key)

        if not node:
            return node

        self.update_height(node)
        balance = self.get_balance(node)

        # Left Left Case
        if balance > 1 and self.get_balance(node.left) >= 0:
            return self.rotate_right(node)

        # Left Right Case
        if balance > 1 and self.get_balance(node.left) < 0:
            node.left = self.rotate_left(node.left)
            return self.rotate_right(node)

        # Right Right Case
        if balance < -1 and self.get_balance(node.right) <= 0:
            return self.rotate_left(node)

        # Right Left Case
        if balance < -1 and self.get_balance(node.right) > 0:
            node.right = self.rotate_right(node.right)
            return self.rotate_left(node)

        return node

    def _min_value_node(self, node):
        """Find node with minimum key value."""
        current = node
        while current.left:
            current = current.left
        return current

    def search(self, key):
        """Search for a key in the tree."""
        return self._search(self.root, key)

    def _search(self, node, key):
        """Recursive helper for search."""
        if not node or node.key == key:
            return node
        if key < node.key:
            return self._search(node.left, key)
        return self._search(node.right, key)

    def contains(self, key):
        """Check if key exists in the tree."""
        return self.search(key) is not None

    def inorder_traversal(self):
        """Return inorder traversal of tree."""
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node, result):
        """Recursive helper for inorder traversal."""
        if node:
            self._inorder(node.left, result)
            result.append((node.key, node.value))
            self._inorder(node.right, result)

    def preorder_traversal(self):
        """Return preorder traversal of tree."""
        result = []
        self._preorder(self.root, result)
        return result

    def _preorder(self, node, result):
        """Recursive helper for preorder traversal."""
        if node:
            result.append((node.key, node.value))
            self._preorder(node.left, result)
            self._preorder(node.right, result)

    def postorder_traversal(self):
        """Return postorder traversal of tree."""
        result = []
        self._postorder(self.root, result)
        return result

    def _postorder(self, node, result):
        """Recursive helper for postorder traversal."""
        if node:
            self._postorder(node.left, result)
            self._postorder(node.right, result)
            result.append((node.key, node.value))

    def is_balanced(self):
        """Check if tree is balanced."""
        return self._is_balanced(self.root)

    def _is_balanced(self, node):
        """Recursive helper to check balance."""
        if not node:
            return True

        balance = self.get_balance(node)
        return (abs(balance) <= 1 and 
                self._is_balanced(node.left) and 
                self._is_balanced(node.right))

    def get_height_tree(self):
        """Get height of the entire tree."""
        return self.get_height(self.root)

    def clear(self):
        """Clear the tree."""
        self.root = None

    def __len__(self):
        """Return number of nodes in tree."""
        return len(self.inorder_traversal())

    def __contains__(self, key):
        """Support 'in' operator."""
        return self.contains(key)

    def __str__(self):
        """String representation of tree."""
        items = self.inorder_traversal()
        return f"AVLTree({items})"


